import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { sendOtp } from '../api';

export default function Signup() {
  const [type, setType] = useState('email');
  const [contact, setContact] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await sendOtp({ type, contact });
      navigate('/verify-otp', { state: { type, contact } });
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to send OTP');
    } finally {
      setLoading(false);
    }
  };

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="max-w-xl mx-auto mt-16 bg-slate-800 rounded-xl shadow-lg p-8">
      <h1 className="text-2xl font-bold mb-4">Signup for Smart Budget Trip Planner</h1>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex space-x-4">
          <label className="flex items-center">
            <input type="radio" name="type" value="email" checked={type === 'email'} onChange={(e) => setType(e.target.value)} className="mr-2" />
            Email
          </label>
          <label className="flex items-center">
            <input type="radio" name="type" value="phone" checked={type === 'phone'} onChange={(e) => setType(e.target.value)} className="mr-2" />
            Phone
          </label>
        </div>
        <input
          name="contact"
          value={contact}
          onChange={(e) => setContact(e.target.value)}
          placeholder={type === 'email' ? 'Email' : 'Phone Number (with country code, e.g. +91XXXXXXXXXX)'}
          className="w-full p-3 rounded-lg bg-slate-700"
          required
        />
        {error && <p className="text-red-400">{error}</p>}
        <button type="submit" disabled={loading} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-semibold transition">
          {loading ? 'Sending OTP...' : 'Send OTP'}
        </button>
      </form>
      <p className="mt-4 text-sm text-slate-300">Already have account? <Link to="/login" className="text-cyan-300">Login</Link></p>
    </motion.div>
  );
}
